// Rebuild the offline adapter from shared validation/matching sources. Existing
// app engines and the source catalogue remain authoritative and are not bundled
// a second time. --check verifies both generated files without writing.
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';
import { realpathSync } from 'node:fs';
import { readFile, writeFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { relative, resolve } from 'node:path';
import { runInNewContext } from 'node:vm';
import assert from 'node:assert/strict';

const require = createRequire(realpathSync(new URL('../node_modules/wrangler/package.json', import.meta.url)));
const { build } = require('esbuild');
const root = fileURLToPath(new URL('../../', import.meta.url));
const outfile = resolve(root, 'Web/core/fast-food-capture.js');
const manifestfile = resolve(root, 'Backend/scripts/fast-food-capture.sources.json');
const check = process.argv.includes('--check');
const dependencyPaths = ['Web/core/nudge-score.js', 'Web/core/food-composition.js', 'Web/core/meal-recovery-data.js',
  'Web/core/meal-recovery.js', 'Web/core/recipe-composition.js', 'Web/core/meal-score.js'];
const dataPaths = ['Backend/data/cofid-2021.json', 'Backend/data/usda-meal-fallbacks.json', 'Backend/data/usda-recipe-measures.json'];
const contents = await Promise.all(dataPaths.map(path => readFile(resolve(root, path), 'utf8')));
const [cofid, usda, measures] = contents.map(text => JSON.parse(text));
const sandbox = {};
runInNewContext(await readFile(resolve(root, 'Web/core/meal-recovery-data.js'), 'utf8'), sandbox);
const data = JSON.parse(JSON.stringify(sandbox.NudgeMealRecoveryData));
const values = tuple => Object.fromEntries(data.keys.map((key, i) => [key, tuple[8][i]]));
const cofidFoods = data.records.filter(row => row[1] === 'c').map(row => ({ id: row[0], code: row[2], name: row[3],
  description: row[4], reference: row[5], values: values(row) }));
// Fail a rebuild if the existing bundled index no longer reproduces a complete
// authoritative source row. This is reuse, never field-by-field nutrition mixing.
assert.deepEqual(cofidFoods, cofid.foods, 'Bundled CoFID records must exactly match the backend source');
const usdaDescriptors = usda.foods.map(({ values: originalValues, ...row }) => {
  const tuple = data.records.find(tuple => tuple[0] === row.id);
  assert.ok(tuple, 'Missing bundled USDA record: ' + row.id);
  const restored = Object.fromEntries(Object.keys(originalValues).map(key => [key, values(tuple)[key]]));
  assert.deepEqual(restored, originalValues, 'Bundled USDA values must exactly match ' + row.id);
  assert.equal(tuple[2], row.code); assert.equal(tuple[3], row.name);
  return { ...row, valueKeys: Object.keys(originalValues) };
});
const withoutFoods = ({ foods, ...metadata }) => metadata;
const dataPrelude = `const data=globalThis.NudgeMealRecoveryData;if(!data||data.version!==${JSON.stringify(data.version)})throw new Error('Bundled food data is unavailable.');\n`;
const virtual = {
  cores: `const root=globalThis;
    const Composition=root.NudgeComposition,MealRecovery=root.NudgeMealRecovery,RecipeComposition=root.NudgeRecipeComposition;
    if(!Composition||!MealRecovery||!RecipeComposition)throw new Error('Bundled food engines are unavailable.');
    export {Composition,MealRecovery,RecipeComposition};`,
  cofid: dataPrelude + `const foods=data.records.filter(row=>row[1]==='c').map(row=>({id:row[0],code:row[2],name:row[3],description:row[4],reference:row[5],values:Object.fromEntries(data.keys.map((key,i)=>[key,row[8][i]]))}));
    export default {...${JSON.stringify(withoutFoods(cofid))},foods};`,
  usda: dataPrelude + `const index=new Map(data.records.map(row=>[row[0],row]));
    const foods=${JSON.stringify(usdaDescriptors)}.map(({valueKeys,...row})=>({...row,values:Object.fromEntries(valueKeys.map(key=>[key,index.get(row.id)[8][data.keys.indexOf(key)]]))}));
    export default {...${JSON.stringify(withoutFoods(usda))},foods};`,
  // Recipe measures use only household weights and provenance, never this JSON's
  // duplicate nutrient rows. Their nutrient records come from shared composition.
  measures: `export default ${JSON.stringify(withoutFoods(measures))};`
};
const result = await build({
  absWorkingDir: root, entryPoints: [resolve(root, 'Backend/src/fast-food-capture.js')], outfile,
  bundle: true, platform: 'browser', target: 'es2022', format: 'iife', minify: true,
  write: false, metafile: true, logLevel: 'silent', legalComments: 'inline',
  inject: [resolve(root, 'Backend/scripts/chatgpt-browser-runtime.js')],
  banner: { js: '// Generated by Backend/scripts/build-fast-food-capture.mjs. Shared source remains authoritative.' },
  plugins: [{ name: 'existing-nudge-engines', setup(builder) {
    builder.onResolve({ filter: /nutrition-core\.js$/ }, () => ({ path: 'cores', namespace: 'nudge-existing' }));
    builder.onResolve({ filter: /(?:cofid-2021|usda-meal-fallbacks|usda-recipe-measures)\.json$/ }, args => ({
      path: args.path.includes('cofid-2021') ? 'cofid' : args.path.includes('usda-meal-fallbacks') ? 'usda' : 'measures', namespace: 'nudge-existing'
    }));
    builder.onLoad({ filter: /.*/, namespace: 'nudge-existing' }, args => ({ contents: virtual[args.path], loader: 'js' }));
  } }]
});
const sha256 = bytes => createHash('sha256').update(bytes).digest('hex');
const paths = new Set([...dependencyPaths, ...dataPaths, 'Backend/scripts/build-fast-food-capture.mjs']);
for (const input of Object.keys(result.metafile.inputs)) {
  if (input.startsWith('nudge-existing:')) continue;
  const path = relative(root, resolve(root, input));
  if (path.startsWith('..') || path.includes('node_modules')) throw new Error('Unexpected browser dependency: ' + path);
  paths.add(path);
}
const sources = {};
for (const path of [...paths].sort()) sources[path] = sha256(await readFile(resolve(root, path)));
const output = result.outputFiles[0].contents;
const manifest = JSON.stringify({ version: 1, bundle: relative(root, outfile), sha256: sha256(output), sources }, null, 2) + '\n';
if (check) {
  assert.deepEqual(await readFile(outfile), Buffer.from(output), 'Rebuild the fast food capture bundle');
  assert.equal(await readFile(manifestfile, 'utf8'), manifest, 'Rebuild the fast food capture source manifest');
} else {
  await writeFile(outfile, output); await writeFile(manifestfile, manifest);
}
console.log(`Fast food capture adapter ${check ? 'verified' : 'built'}: ${output.length} bytes; ${Object.keys(sources).length} pinned sources; existing engines and nutrient data reused.`);
